// This file is generated by AI.

// 配音编辑模式的交互入口。
//
// 配音工作台是**一个普通选项卡**, 因此这里不需要任何"开关"状态:
// * 打开工作台 = 打开 (或聚焦) 那个选项卡;
// * 关闭工作台 = 关闭那个选项卡;
// * "工作台是否打开" 一律由选项卡序列推导 (`isVoiceWorkbenchOpen`)。
//
// 场景的配音编辑模式规则收敛在 store 内部:
// 工作台存在时, 当前场景卡自动进入; 关闭工作台即全部退出。
//
// 这里另外承担"有任务没跑完时先问一句"的职责 —— 三处都走同一个确认框 (`confirm.ts`),
// 而不是 `window.confirm` (它在 WebView 里不一定真的弹出来, 于是询问会变成悄悄放行)。

import { requestConfirm } from '../confirm';
import { activeSceneDocumentOf, isVoiceWorkbenchOpen, isVoiceWorkbenchActive, useAppStore } from '../state/store';
import { voiceController } from './controller';

/** 打开配音工作台选项卡 (当前场景卡会自动进入配音编辑模式) */
export function openVoiceWorkbench(): void {
  useAppStore.getState().openVoiceWorkbench();
}

/**
 * 关闭配音工作台。
 *
 * 还有任务没跑完时先问一句 —— 关闭工作台会:
 * * **撤下这些任务**: 工作台一关服务就停, 留着它们只会是"永远等不到结果的排队中";
 * * **停掉 GSOV 服务**: 工作台就是这个功能的开关, 没必要让一个几 GB 的推理进程继续
 *   占着显存与端口 (停止期间状态栏显示「停止中…」)。
 *
 * 历史记录 (已经生成出来的那些) 不受影响。
 */
export function closeVoiceWorkbench(): void {
  const store = useAppStore.getState();
  if (store.voiceQueuePending > 0) {
    requestConfirm({
      title: '还有配音任务未完成',
      description: `关闭配音工作台会取消这 ${store.voiceQueuePending} 个任务并停止 GSOV 服务。已经生成出来的记录不受影响。`,
      confirmLabel: '关闭并取消',
      danger: true,
      action: reallyClose,
    });
    return;
  }
  reallyClose();
}

function reallyClose(): void {
  // 先撤下未完成的任务再关: 服务马上就停, 悬在半空的请求不会自己回来
  voiceController.cancelUnfinishedTasks();
  useAppStore.getState().closeVoiceWorkbench();
  void voiceController.stopGsvIfRunning();
}

/** 切换配音工作台 */
export function toggleVoiceWorkbench(): void {
  const store = useAppStore.getState();
  if (isVoiceWorkbenchOpen(store.tabs)) closeVoiceWorkbench();
  else store.openVoiceWorkbench();
}

/** 配音工作台选项卡是否打开 */
export function voiceWorkbenchOpen(): boolean {
  return isVoiceWorkbenchOpen(useAppStore.getState().tabs);
}

/** 配音工作台选项卡是否处于激活状态 (即当前正显示它) */
export function voiceWorkbenchActive(): boolean {
  return isVoiceWorkbenchActive(useAppStore.getState());
}

/** 指定场景是否处于配音编辑模式 */
export function isSceneInVoiceMode(path: string): boolean {
  return useAppStore.getState().voiceModePaths.includes(path);
}

/** 当前活动场景是否处于配音编辑模式 */
export function activeSceneInVoiceMode(): boolean {
  const store = useAppStore.getState();
  const scene = activeSceneDocumentOf(store);
  return scene ? store.voiceModePaths.includes(scene.path) : false;
}

/**
 * 切换指定场景的配音编辑模式。
 *
 * **离开配音卡时先问一句**: 该场景还有没跑完的任务时, 用户点麦克风很可能是想"再看一眼"
 * 而不是真的要离开。任务本身不会因为离开而中止 (队列是全局的, 历史也已落盘), 但看不见
 * 进度的等待很容易被当成卡死。
 */
export function setSceneVoiceMode(path: string, enabled: boolean): void {
  const leave = () => useAppStore.getState().setVoiceMode(path, false);
  if (enabled) {
    useAppStore.getState().setVoiceMode(path, true);
    return;
  }
  const count = voiceController.unfinishedCount(path);
  if (count > 0) {
    requestConfirm({
      title: '这个场景还有配音任务',
      description: `还有 ${count} 个任务没跑完。离开配音卡不会取消它们 —— 任务会继续在队列里执行，进度可以在配音工作台里看。`,
      confirmLabel: '离开',
      action: leave,
    });
    return;
  }
  leave();
}
